changeSet.sql:
ALTER TABLE krrg_vacancies ADD COLUMN source_id BIGINT;

UPDATE krrg_vacancies v
SET source_id = s.id
    FROM krrg_vacancy_sources s
WHERE s.code = v.source;

ALTER TABLE krrg_vacancies ALTER COLUMN source_id SET NOT NULL;

ALTER TABLE krrg_vacancies DROP CONSTRAINT IF EXISTS krrg_vacancies_source_check;
ALTER TABLE krrg_vacancies DROP CONSTRAINT IF EXISTS ukkkpga0nd24lek2grtndx1fcy5;
ALTER TABLE krrg_vacancies DROP COLUMN source;

ALTER TABLE krrg_vacancies
    ADD CONSTRAINT fk_vacancies__source
        FOREIGN KEY (source_id) REFERENCES krrg_vacancy_sources (id) ON DELETE RESTRICT;
ALTER TABLE krrg_vacancies
    ADD CONSTRAINT uk_vacancies__external_id_source UNIQUE (external_id, source_id);
CREATE INDEX IF NOT EXISTS idx_vacancies__source_id ON krrg_vacancies (source_id);

rollback.sql:
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS source VARCHAR(20);
UPDATE krrg_vacancies v SET source = s.code
FROM krrg_vacancy_sources s WHERE s.id = v.source_id;
ALTER TABLE krrg_vacancies ALTER COLUMN source SET NOT NULL;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS source_id;
ALTER TABLE krrg_vacancies
ADD CONSTRAINT krrg_vacancies_source_check CHECK (((source)::text = 'HH'::text));
ALTER TABLE krrg_vacancies
ADD CONSTRAINT ukkkpga0nd24lek2grtndx1fcy5 UNIQUE (external_id, source);

changeSet.sql:
CREATE TABLE krrg_vacancy_grades ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(20) NOT NULL, name VARCHAR(50) NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP(6), updated_at TIMESTAMP(6), CONSTRAINT uk_vacancy_grades__code UNIQUE (code) );
INSERT INTO krrg_vacancy_grades (code, name, sort_order, created_at, updated_at) VALUES ('JUNIOR', 'Junior', 1, now(), now()), ('JUNIOR_PLUS', 'Junior+', 2, now(), now()), ('MIDDLE', 'Middle', 3, now(), now()), ('SENIOR', 'Senior', 4, now(), now());
CREATE TABLE krrg_vacancy_grade_link ( vacancy_id BIGINT NOT NULL, grade_id BIGINT NOT NULL, CONSTRAINT pk_vacancy_grade_link PRIMARY KEY (vacancy_id, grade_id), CONSTRAINT fk_vacancy_grade_link__vacancy FOREIGN KEY (vacancy_id) REFERENCES krrg_vacancies (id) ON DELETE CASCADE, CONSTRAINT fk_vacancy_grade_link__grade FOREIGN KEY (grade_id) REFERENCES krrg_vacancy_grades (id) ON DELETE RESTRICT ); CREATE INDEX IF NOT EXISTS idx_vacancy_grade_link__grade_id ON krrg_vacancy_grade_link (grade_id);

ALTER TABLE krrg_vacancies ALTER COLUMN url DROP NOT NULL; ALTER TABLE krrg_vacancies ALTER COLUMN external_id DROP NOT NULL;
ALTER TABLE krrg_vacancies ADD COLUMN category_id BIGINT, ADD COLUMN rate_resident NUMERIC(12, 2), ADD COLUMN rate_non_resident NUMERIC(12, 2), ADD COLUMN rate_currency VARCHAR(3), ADD COLUMN rate_unit VARCHAR(20), ADD COLUMN specialists_count INTEGER, ADD COLUMN work_format VARCHAR(20), ADD COLUMN location VARCHAR(1000), ADD COLUMN duration_months INTEGER, ADD COLUMN indefinite BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN raw_text TEXT;
ALTER TABLE krrg_vacancies ADD CONSTRAINT fk_vacancies__category FOREIGN KEY (category_id) REFERENCES krrg_vacancy_categories (id) ON DELETE RESTRICT; CREATE INDEX IF NOT EXISTS idx_vacancies__category_id ON krrg_vacancies (category_id);

INSERT INTO krrg_vacancy_owner_organisation (name, description, created_at, updated_at)
SELECT 'Банки и финансы', 'Обезличенный заказчик из отрасли «Банки и финансы»', now(), now()
    WHERE NOT EXISTS (
    SELECT 1 FROM krrg_vacancy_owner_organisation WHERE name = 'Банки и финансы'
);

UPDATE krrg_vacancy_sources
SET code = 'SKILLSTAF', name = 'Skillstaf', updated_at = now()
WHERE code = 'ORDER';

INSERT INTO krrg_vacancy_sources (code, name, created_at, updated_at)
SELECT 'SKILLSTAF', 'Skillstaf', now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM krrg_vacancy_sources WHERE code = 'SKILLSTAF');

